class Solution {public int[][] solve(int[][] g){int m=g.length,n=m==0?0:g[0].length;int[][] d=new int[m][n];ArrayList<int[]>q=new ArrayList<>();for(int r=0;r<m;r++)for(int c=0;c<n;c++){d[r][c]=g[r][c]==1?-2:-1;if(g[r][c]==2){d[r][c]=0;q.add(new int[]{r,c});}}int[] dr={-1,1,0,0},dc={0,0,-1,1};for(int i=0;i<q.size();i++){int r=q.get(i)[0],c=q.get(i)[1];for(int k=0;k<4;k++){int x=r+dr[k],y=c+dc[k];if(x>=0&&x<m&&y>=0&&y<n&&d[x][y]==-1){d[x][y]=d[r][c]+1;q.add(new int[]{x,y});}}}return d;}}